// Command releasediff is the PREVIOUS-RELEASE DIFFERENTIAL GATE
// (docs/VERSIONING.md, "The packet wire and the protocol id"; #463): the
// corpus generated by the previous release and by the new one, byte-compared
// under an equal protocol id.
//
//	releasediff [-prev vX.Y.Z] [-rev REV] [-old-bin PATH] [-new-bin PATH]
//	            [-corpus DIR] [-work DIR] [-j N]
//
// The invariant it proves is the page's: no generated byte may change for the
// same schema without the protocol id changing. So both compilers, the newest
// v tag's (-prev, default the newest) and REV's (default HEAD), are built from
// their own trees, and every unit of the corpus is handed to both:
//
//   - THE CORPUS is the units `make check` names, read from the `check:`
//     recipe of REV's Makefile, as REV's tree holds them. Both compilers read
//     the same files.
//   - A unit whose protocol id is EQUAL under both compilers is generated by
//     both in every target both carry, and the two trees must be the same
//     listing and the same bytes. A difference refuses, naming the unit, the
//     target, the file and the first differing byte.
//   - A unit whose protocol id MOVED is listed and not compared: the id is
//     what tells two builds apart, and it did.
//   - A unit either compiler refuses has no id on that side, so no equal id;
//     it is listed. So is a target only one side carries, and a target one
//     side refuses for the unit: neither can hold two peers on one id with two
//     wires.
//
// It exits 1 on any difference and 0 otherwise. -old-bin and -new-bin take
// prebuilt compilers instead of building them (the negative control hands it
// a sabotaged one), and -corpus reads the units from a directory instead of
// REV's tree.
//
// The decisions are pure functions (CheckUnits, ParseTargets,
// FirstDifference, CompareTrees, Judge) unit-tested with no git and no
// compiler; only main execs git, go and the two compilers.
package main

import (
	"archive/tar"
	"bytes"
	"errors"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"slices"
	"strconv"
	"strings"
	"sync"
)

// CheckUnits reads the corpus out of a Makefile: every `./bin/schema check`
// line of the `check:` recipe is one unit, its arguments the unit's paths.
func CheckUnits(makefile string) ([][]string, error) {
	var units [][]string
	in := false
	for line := range strings.SplitSeq(makefile, "\n") {
		if strings.HasPrefix(line, "check:") {
			in = true
			continue
		}
		if !in {
			continue
		}
		if !strings.HasPrefix(line, "\t") {
			break
		}
		f := strings.Fields(line)
		if len(f) >= 3 && f[0] == "./bin/schema" && f[1] == "check" {
			units = append(units, f[2:])
		}
	}
	if len(units) == 0 {
		return nil, errors.New("the Makefile's check: recipe names no `./bin/schema check` unit; the corpus is empty")
	}
	return units, nil
}

var targetList = regexp.MustCompile(`target language \(([a-z0-9, ]+)\)`)

// ParseTargets reads a compiler's targets out of `schema generate -h`, whose
// -lang flag lists them: "target language (c, cpp, ...)".
func ParseTargets(help string) ([]string, error) {
	m := targetList.FindStringSubmatch(help)
	if m == nil {
		return nil, errors.New("`generate -h` names no target list")
	}
	var out []string
	for t := range strings.SplitSeq(m[1], ",") {
		if t = strings.TrimSpace(t); t != "" {
			out = append(out, t)
		}
	}
	return out, nil
}

// FirstDifference is the offset of the first byte at which a and b differ,
// the shorter length when one is a prefix of the other, and -1 when equal.
func FirstDifference(a, b []byte) int {
	n := min(len(a), len(b))
	for i := range n {
		if a[i] != b[i] {
			return i
		}
	}
	if len(a) != len(b) {
		return n
	}
	return -1
}

// Difference is the first place two generated trees disagree.
type Difference struct {
	File   string // slash-separated, relative to the tree
	Offset int    // the first differing byte; -1 when the file is on one side only
	Line   int    // the 1-based line holding Offset in the previous tree's file
	Old    int    // the byte there in the previous tree, -1 past its end or absent
	New    int    // the byte there in the new tree, -1 past its end or absent
	Files  int    // how many files differ in all, this one included
}

func (d *Difference) String() string {
	if d.Offset < 0 {
		side := "previous release only"
		if d.Old < 0 {
			side = "new compiler only"
		}
		return fmt.Sprintf("%s is emitted by the %s (%d file(s) differ)", d.File, side, d.Files)
	}
	return fmt.Sprintf("%s first differs at byte %d (line %d): previous %s, new %s (%d file(s) differ)",
		d.File, d.Offset, d.Line, byteText(d.Old), byteText(d.New), d.Files)
}

func byteText(b int) string {
	if b < 0 {
		return "end of file"
	}
	return fmt.Sprintf("0x%02x %s", b, strconv.QuoteRune(rune(b)))
}

func listing(root string) (map[string]bool, error) {
	files := map[string]bool{}
	err := filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(root, p)
		if err != nil {
			return err
		}
		files[filepath.ToSlash(rel)] = true
		return nil
	})
	return files, err
}

// CompareTrees compares two generated trees both ways, listing and bytes, and
// returns nil when they are the same, or the first difference in path order.
func CompareTrees(oldDir, newDir string) (*Difference, error) {
	oldFiles, err := listing(oldDir)
	if err != nil {
		return nil, err
	}
	newFiles, err := listing(newDir)
	if err != nil {
		return nil, err
	}
	all := map[string]bool{}
	for f := range oldFiles {
		all[f] = true
	}
	for f := range newFiles {
		all[f] = true
	}
	names := make([]string, 0, len(all))
	for f := range all {
		names = append(names, f)
	}
	slices.Sort(names)
	var first *Difference
	count := 0
	for _, f := range names {
		var d *Difference
		switch {
		case !newFiles[f]:
			d = &Difference{File: f, Offset: -1, Old: 0, New: -1}
		case !oldFiles[f]:
			d = &Difference{File: f, Offset: -1, Old: -1, New: 0}
		default:
			a, err := os.ReadFile(filepath.Join(oldDir, filepath.FromSlash(f)))
			if err != nil {
				return nil, err
			}
			b, err := os.ReadFile(filepath.Join(newDir, filepath.FromSlash(f)))
			if err != nil {
				return nil, err
			}
			off := FirstDifference(a, b)
			if off < 0 {
				continue
			}
			d = &Difference{File: f, Offset: off, Line: 1 + bytes.Count(a[:min(off, len(a))], []byte("\n")), Old: at(a, off), New: at(b, off)}
		}
		count++
		if first == nil {
			first = d
		}
	}
	if first != nil {
		first.Files = count
	}
	return first, nil
}

func at(b []byte, i int) int {
	if i < len(b) {
		return int(b[i])
	}
	return -1
}

// Compiler is one side of the differential: a schema compiler run over the
// corpus.
type Compiler interface {
	// Name says which side it is, in every line the gate prints.
	Name() string
	// Targets lists the generate targets it carries.
	Targets() ([]string, error)
	// ID is the unit's protocol id, or an error when it refuses the unit.
	ID(unit []string) (string, error)
	// Generate emits the unit in one target into out, an empty directory,
	// or returns an error when it refuses.
	Generate(unit []string, lang, out string) error
}

// Report is everything one run found.
type Report struct {
	Compared    []string // "unit (id)": equal id, every shared target compared
	Moved       []string // "unit: old -> new"
	Unreadable  []string // "unit: who refuses it"
	Uncompared  []string // a target one side lacks or refuses for a unit
	Differences []string // the refusals
}

// Judge runs the differential over units with old and new, generating into
// work, at most jobs generations at once.
func Judge(old, new Compiler, units [][]string, work string, jobs int) (*Report, error) {
	oldTargets, err := old.Targets()
	if err != nil {
		return nil, fmt.Errorf("%s: %w", old.Name(), err)
	}
	newTargets, err := new.Targets()
	if err != nil {
		return nil, fmt.Errorf("%s: %w", new.Name(), err)
	}
	var shared []string
	r := &Report{}
	for _, t := range newTargets {
		if slices.Contains(oldTargets, t) {
			shared = append(shared, t)
		} else {
			r.Uncompared = append(r.Uncompared, fmt.Sprintf("target %s: %s does not carry it", t, old.Name()))
		}
	}
	for _, t := range oldTargets {
		if !slices.Contains(newTargets, t) {
			r.Uncompared = append(r.Uncompared, fmt.Sprintf("target %s: %s does not carry it", t, new.Name()))
		}
	}

	type pair struct {
		unit int
		lang string
	}
	var work2 []pair
	for i, u := range units {
		name := strings.Join(u, " ")
		oid, oerr := old.ID(u)
		nid, nerr := new.ID(u)
		switch {
		case oerr != nil && nerr != nil:
			r.Unreadable = append(r.Unreadable, fmt.Sprintf("%s: both compilers refuse it", name))
		case oerr != nil:
			r.Unreadable = append(r.Unreadable, fmt.Sprintf("%s: %s refuses it (%s)", name, old.Name(), firstLine(oerr)))
		case nerr != nil:
			r.Unreadable = append(r.Unreadable, fmt.Sprintf("%s: %s refuses it (%s)", name, new.Name(), firstLine(nerr)))
		case oid != nid:
			r.Moved = append(r.Moved, fmt.Sprintf("%s: %s -> %s", name, oid, nid))
		default:
			r.Compared = append(r.Compared, fmt.Sprintf("%s (protocol id %s)", name, oid))
			for _, t := range shared {
				work2 = append(work2, pair{i, t})
			}
		}
	}

	type result struct {
		uncompared, difference string
	}
	results := make([]result, len(work2))
	sem := make(chan struct{}, max(jobs, 1))
	var wg sync.WaitGroup
	var fatal error
	var mu sync.Mutex
	for k, p := range work2 {
		wg.Add(1)
		sem <- struct{}{}
		go func() {
			defer wg.Done()
			defer func() { <-sem }()
			u := units[p.unit]
			name := strings.Join(u, " ")
			od := filepath.Join(work, "old", strconv.Itoa(p.unit), p.lang)
			nd := filepath.Join(work, "new", strconv.Itoa(p.unit), p.lang)
			oerr := old.Generate(u, p.lang, od)
			nerr := new.Generate(u, p.lang, nd)
			switch {
			case oerr != nil && nerr != nil:
				results[k].uncompared = fmt.Sprintf("%s --lang %s: both compilers refuse it", name, p.lang)
			case oerr != nil:
				results[k].uncompared = fmt.Sprintf("%s --lang %s: %s refuses it (%s)", name, p.lang, old.Name(), firstLine(oerr))
			case nerr != nil:
				results[k].uncompared = fmt.Sprintf("%s --lang %s: %s refuses it (%s)", name, p.lang, new.Name(), firstLine(nerr))
			default:
				d, err := CompareTrees(od, nd)
				if err != nil {
					mu.Lock()
					fatal = errors.Join(fatal, err)
					mu.Unlock()
					return
				}
				if d != nil {
					results[k].difference = fmt.Sprintf("%s --lang %s: %s", name, p.lang, d)
				}
			}
		}()
	}
	wg.Wait()
	if fatal != nil {
		return nil, fatal
	}
	for _, res := range results {
		if res.uncompared != "" {
			r.Uncompared = append(r.Uncompared, res.uncompared)
		}
		if res.difference != "" {
			r.Differences = append(r.Differences, res.difference)
		}
	}
	return r, nil
}

func firstLine(err error) string {
	s := strings.TrimSpace(err.Error())
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		s = s[:i]
	}
	return s
}

// Print writes the report: what was compared, what was listed and why, and
// every difference.
func (r *Report) Print(w io.Writer, oldName, newName string) {
	_, _ = fmt.Fprintf(w, "release-differential: %s -> %s, under an equal protocol id\n", oldName, newName)
	section := func(title string, lines []string) {
		for _, l := range lines {
			_, _ = fmt.Fprintf(w, "  %-12s %s\n", title, l)
		}
	}
	section("compared", r.Compared)
	section("id moved", r.Moved)
	section("unreadable", r.Unreadable)
	section("uncompared", r.Uncompared)
	for _, d := range r.Differences {
		_, _ = fmt.Fprintf(w, "DIFFERENCE under an equal protocol id: %s\n", d)
	}
	if len(r.Differences) > 0 {
		_, _ = fmt.Fprintf(w, "release-differential: REFUSED, %d unit-target pair(s) generate different bytes under an equal protocol id (%d unit(s) compared)\n", len(r.Differences), len(r.Compared))
		return
	}
	_, _ = fmt.Fprintf(w, "release-differential: ok, %d unit(s) compared byte for byte in every shared target, %d with a moved id\n", len(r.Compared), len(r.Moved))
}

// binary is a compiler binary, run with the corpus root as its directory.
type binary struct {
	name, path, corpus string
}

func (b binary) Name() string { return b.name }

func (b binary) run(args ...string) (string, error) {
	cmd := exec.Command(b.path, args...)
	cmd.Dir = b.corpus
	var out, errb bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errb
	if err := cmd.Run(); err != nil {
		msg := strings.TrimSpace(errb.String())
		// a refusal's own line, not the warnings before it
		lines := strings.Split(msg, "\n")
		for i := len(lines) - 1; i >= 0; i-- {
			if strings.HasPrefix(lines[i], "schema:") {
				msg = lines[i]
				break
			}
		}
		return "", fmt.Errorf("%s", msg)
	}
	return out.String(), nil
}

func (b binary) Targets() ([]string, error) {
	cmd := exec.Command(b.path, "generate", "-h")
	cmd.Dir = b.corpus
	out, _ := cmd.CombinedOutput() // -h exits 2 by the flag package's rule
	return ParseTargets(string(out))
}

func (b binary) ID(unit []string) (string, error) {
	out, err := b.run(append([]string{"id"}, unit...)...)
	if err != nil {
		return "", err
	}
	f := strings.Fields(out)
	for i := len(f) - 1; i >= 0; i-- {
		if strings.HasPrefix(f[i], "0x") {
			return f[i], nil
		}
	}
	return "", fmt.Errorf("`id` printed no id: %q", out)
}

func (b binary) Generate(unit []string, lang, out string) error {
	if err := os.MkdirAll(out, 0o755); err != nil {
		return err
	}
	_, err := b.run(append([]string{"generate", "--lang", lang, "--out", out}, unit...)...)
	return err
}

func git(args ...string) ([]byte, error) {
	cmd := exec.Command("git", args...)
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
	}
	return out, nil
}

var versionForm = regexp.MustCompile(`^v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$`)

// NewestRelease is the greatest vMAJOR.MINOR.PATCH among tags, in numeric
// order; anything else (promotion tags, pre-releases) is ignored.
func NewestRelease(tags []string) (string, bool) {
	var best [3]uint64
	name, found := "", false
	for _, t := range tags {
		m := versionForm.FindStringSubmatch(t)
		if m == nil {
			continue
		}
		var v [3]uint64
		for i := range v {
			v[i], _ = strconv.ParseUint(m[i+1], 10, 64)
		}
		if !found || slices.Compare(best[:], v[:]) < 0 {
			best, name, found = v, t, true
		}
	}
	return name, found
}

// extract writes rev's tree into dir, from `git archive`.
func extract(rev, dir string) error {
	cmd := exec.Command("git", "archive", "--format=tar", rev)
	cmd.Stderr = os.Stderr
	pipe, err := cmd.StdoutPipe()
	if err != nil {
		return err
	}
	if err := cmd.Start(); err != nil {
		return err
	}
	tr := tar.NewReader(pipe)
	for {
		h, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return err
		}
		p := filepath.Join(dir, filepath.FromSlash(h.Name))
		if !strings.HasPrefix(p, filepath.Clean(dir)+string(os.PathSeparator)) {
			return fmt.Errorf("archive entry %q leaves %s", h.Name, dir)
		}
		switch h.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(p, 0o755); err != nil {
				return err
			}
		case tar.TypeReg:
			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
				return err
			}
			f, err := os.OpenFile(p, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, fs.FileMode(h.Mode)&0o777)
			if err != nil {
				return err
			}
			if _, err := io.Copy(f, tr); err != nil {
				_ = f.Close()
				return err
			}
			if err := f.Close(); err != nil {
				return err
			}
		case tar.TypeSymlink:
			if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
				return err
			}
			if err := os.Symlink(h.Linkname, p); err != nil {
				return err
			}
		}
	}
	return cmd.Wait()
}

// build compiles ./cmd/schema of the tree at src into out.
func build(src, out string) error {
	cmd := exec.Command("go", "build", "-o", out, "./cmd/schema")
	cmd.Dir = src
	cmd.Stdout = os.Stderr
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func main() {
	prev := flag.String("prev", "", "the previous release, a v tag (default: the newest v tag)")
	rev := flag.String("rev", "HEAD", "the commit whose compiler and corpus are the new side")
	oldBin := flag.String("old-bin", "", "a prebuilt previous compiler (default: build -prev's ./cmd/schema)")
	newBin := flag.String("new-bin", "", "a prebuilt new compiler (default: build -rev's ./cmd/schema)")
	corpus := flag.String("corpus", "", "read the corpus from this directory (default: -rev's tree)")
	work := flag.String("work", "build/release-differential", "the scratch directory, emptied first")
	jobs := flag.Int("j", runtime.NumCPU(), "generations at once")
	flag.Parse()
	if err := run(*prev, *rev, *oldBin, *newBin, *corpus, *work, *jobs); err != nil {
		fmt.Fprintf(os.Stderr, "release-differential: %v\n", err)
		os.Exit(1)
	}
}

func run(prev, rev, oldBin, newBin, corpus, work string, jobs int) error {
	work, err := filepath.Abs(work)
	if err != nil {
		return err
	}
	if err := os.RemoveAll(work); err != nil {
		return err
	}
	if prev == "" {
		tags, err := git("tag", "--list", "v*")
		if err != nil {
			return err
		}
		var ok bool
		if prev, ok = NewestRelease(strings.Fields(string(tags))); !ok {
			return errors.New("no v tag: there is no previous release to compare against")
		}
	}
	sha, err := git("rev-parse", "--verify", rev+"^{commit}")
	if err != nil {
		return err
	}
	newName := fmt.Sprintf("%s (%s)", rev, strings.TrimSpace(string(sha))[:12])

	if corpus == "" || newBin == "" {
		src := filepath.Join(work, "new-src")
		if err := extract(rev, src); err != nil {
			return fmt.Errorf("extracting %s: %w", rev, err)
		}
		if corpus == "" {
			corpus = src
		}
		if newBin == "" {
			newBin = filepath.Join(work, "schema-new")
			if err := build(src, newBin); err != nil {
				return fmt.Errorf("building %s's compiler: %w", rev, err)
			}
		}
	}
	if oldBin == "" {
		src := filepath.Join(work, "old-src")
		if err := extract(prev, src); err != nil {
			return fmt.Errorf("extracting %s: %w", prev, err)
		}
		oldBin = filepath.Join(work, "schema-old")
		if err := build(src, oldBin); err != nil {
			return fmt.Errorf("building %s's compiler: %w", prev, err)
		}
	}
	if corpus, err = filepath.Abs(corpus); err != nil {
		return err
	}
	if oldBin, err = filepath.Abs(oldBin); err != nil {
		return err
	}
	if newBin, err = filepath.Abs(newBin); err != nil {
		return err
	}
	mk, err := os.ReadFile(filepath.Join(corpus, "Makefile"))
	if err != nil {
		return err
	}
	units, err := CheckUnits(string(mk))
	if err != nil {
		return err
	}
	old := binary{name: prev, path: oldBin, corpus: corpus}
	nw := binary{name: newName, path: newBin, corpus: corpus}
	r, err := Judge(old, nw, units, filepath.Join(work, "gen"), jobs)
	if err != nil {
		return err
	}
	r.Print(os.Stdout, old.Name(), nw.Name())
	if len(r.Differences) > 0 {
		os.Exit(1)
	}
	return nil
}
